using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32;

namespace ScreenSpanSetup {
static class Program {
    const string Product="ScreenSpan Wallpaper";
    static string InstallFolder=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs",Product);
    static string Exe=>Path.Combine(InstallFolder,Product+".exe");
    const string UninstallKey=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\ScreenSpanWallpaper";
    [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{
        if(args.Length==2&&args[0]=="--self-test"){SelfTest(args[1]);return 0;}
        if(args.Length==2&&args[0]=="--remove"){Remove(int.Parse(args[1]));return 0;}
        if(args.Length==1&&args[0]=="--uninstall"){if(MessageBox.Show("Remove ScreenSpan Wallpaper? Your pictures, saved wallpaper projects and AI models will be kept.",Product,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return 0;CloseRunning();string temporary=Path.Combine(Path.GetTempPath(),"ScreenSpan-Uninstall-"+Guid.NewGuid()+".exe");File.Copy(Application.ExecutablePath,temporary);Process.Start(new ProcessStartInfo{FileName=temporary,Arguments="--remove "+Process.GetCurrentProcess().Id,UseShellExecute=false});return 0;}
        if(args.Length==1&&args[0]=="--install"){Install();return 0;}
        using(var window=new Form{Text="Install "+Product,Size=new Size(600,300),StartPosition=FormStartPosition.CenterScreen,Font=new Font("Segoe UI",11),MaximizeBox=false}){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),FlowDirection=FlowDirection.TopDown,WrapContents=false};panel.Controls.Add(new Label{Text="ScreenSpan Wallpaper for Windows 1.0.1",AutoSize=true,Font=new Font("Segoe UI",16,FontStyle.Bold)});panel.Controls.Add(new Label{Text="Create spanning desktop wallpapers across your displays.\n\nInstalls for your Windows account and adds Desktop and Start menu shortcuts. Your saved pictures are kept when updating or uninstalling.",AutoSize=true,MaximumSize=new Size(530,0)});var install=new Button{Text="Install",AutoSize=true,Margin=new Padding(0,18,0,0)};install.Click+=(s,e)=>{install.Enabled=false;try{Install();MessageBox.Show(window,"ScreenSpan Wallpaper is installed. Open it from your Desktop shortcut.",Product);window.Close();}catch(Exception error){install.Enabled=true;MessageBox.Show(window,error.Message,Product,MessageBoxButtons.OK,MessageBoxIcon.Error);}};panel.Controls.Add(install);window.Controls.Add(panel);Application.Run(window);}return 0;
    }catch(Exception e){if(args.Length==2&&args[0]=="--self-test")File.WriteAllText(Path.Combine(args[1],"installer-failure.txt"),e.ToString());else MessageBox.Show(e.Message,Product,MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
    static void Payload(string path){using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("ScreenSpan.Payload.exe"))using(var output=File.Create(path)){if(input==null)throw new InvalidDataException("The installer payload is missing.");input.CopyTo(output);}}
    static void CloseRunning(){if(!File.Exists(Exe))return;using(var close=Process.Start(new ProcessStartInfo{FileName=Exe,Arguments="--quit",UseShellExecute=false,CreateNoWindow=true})){if(!close.WaitForExit(6000))throw new IOException("Close ScreenSpan Wallpaper and try again.");}for(int attempt=0;attempt<20;attempt++){bool running=false;foreach(var process in Process.GetProcessesByName(Product)){using(process){try{if(string.Equals(process.MainModule.FileName,Exe,StringComparison.OrdinalIgnoreCase))running=true;}catch{}}}if(!running)return;Thread.Sleep(150);}throw new IOException("Close ScreenSpan Wallpaper, including any AI processing, and try again.");}
    static void Shortcut(string path,string target){Directory.CreateDirectory(Path.GetDirectoryName(path)!);Type type=Type.GetTypeFromProgID("WScript.Shell")!;object shell=Activator.CreateInstance(type)!;object shortcut=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path})!;try{shortcut.GetType().InvokeMember("TargetPath",BindingFlags.SetProperty,null,shortcut,new object[]{target});shortcut.GetType().InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,shortcut,new object[]{InstallFolder});shortcut.GetType().InvokeMember("Save",BindingFlags.InvokeMethod,null,shortcut,null);}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
    static void Install(){CloseRunning();Directory.CreateDirectory(InstallFolder);string temporary=Path.Combine(InstallFolder,"Application.new");Payload(temporary);if(File.Exists(Exe))File.Replace(temporary,Exe,null);else File.Move(temporary,Exe);if(!string.Equals(Application.ExecutablePath,Path.Combine(InstallFolder,"Uninstall.exe"),StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,Path.Combine(InstallFolder,"Uninstall.exe"),true);File.WriteAllText(Path.Combine(InstallFolder,"ScreenSpan.install"),"1.0.1");Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Product+".lnk"),Exe);Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),Product,Product+".lnk"),Exe);using(var key=Registry.CurrentUser.CreateSubKey(UninstallKey)){key.SetValue("DisplayName",Product);key.SetValue("DisplayVersion","1.0.1");key.SetValue("Publisher","ScreenSpan Wallpaper");key.SetValue("DisplayIcon",Exe);key.SetValue("InstallLocation",InstallFolder);key.SetValue("UninstallString","\""+Path.Combine(InstallFolder,"Uninstall.exe")+"\" --uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);} }
    static void Remove(int previous){try{using(var process=Process.GetProcessById(previous))process.WaitForExit(10000);}catch(ArgumentException){}if(!File.Exists(Path.Combine(InstallFolder,"ScreenSpan.install")))throw new IOException("This directory was not installed by ScreenSpan Wallpaper.");CloseRunning();foreach(var path in new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Product+".lnk"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),Product,Product+".lnk")})if(File.Exists(path))File.Delete(path);using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){string startup=key?.GetValue("ScreenSpanWallpaper") as string??"";if(startup.IndexOf(Exe,StringComparison.OrdinalIgnoreCase)>=0)key!.DeleteValue("ScreenSpanWallpaper",false);}Registry.CurrentUser.DeleteSubKeyTree(UninstallKey,false);foreach(string name in new[]{Product+".exe","Uninstall.exe","ScreenSpan.install"}){string path=Path.Combine(InstallFolder,name);if(File.Exists(path))File.Delete(path);}if(Directory.GetFileSystemEntries(InstallFolder).Length==0)Directory.Delete(InstallFolder);MessageBox.Show("ScreenSpan Wallpaper was removed. Your saved projects and models have been kept.",Product);}
    static void SelfTest(string root){Directory.CreateDirectory(root);string app=Path.Combine(root,"ScreenSpan Wallpaper.exe");Payload(app);string report=Path.Combine(root,"application-checks.txt");using(var process=Process.Start(new ProcessStartInfo{FileName=app,Arguments="--self-test \""+report+"\"",UseShellExecute=false})){if(!process.WaitForExit(120000)||process.ExitCode!=0)throw new Exception("Packaged standalone application checks failed. Read "+report);}File.WriteAllText(Path.Combine(root,"installer-checks.txt"),"PASS: extracted standalone EXE\nPASS: standalone EXE passed all rendering and project checks without DLL files\nVersion: "+FileVersionInfo.GetVersionInfo(app).FileVersion);}
}
}
